  1	import { readFile, readdir } from 'fs/promises';
  2	import { join } from 'path';
  3	import type { Dirent } from 'fs';
  4	import {
  5	  KnowledgeStoreSchema,
  6	  InsightSchema,
  7	  PROJECT_SLUG_REGEX,
  8	  type KnowledgeStore,
  9	  type Insight,
 10	  type InsightScope,
 11	} from '../schema/knowledge.js';
 12	import { atomicWriteJson } from './atomic-writer.js';
 13	import { withLock } from './file-lock.js';
 14	import { now } from '../utils/timestamp.js';
 15	
 16	/**
 17	 * Manages the `.knowledge/` directory, providing all CRUD operations for
 18	 * insights with atomic writes, file locking, and in-memory search/filter logic.
 19	 *
 20	 * Storage layout (relative to `ledgerRoot`):
 21	 *   .knowledge/
 22	 *     .lock                     — lock file created by withLock
 23	 *     global-insights.json      — insights with scope: 'global'
 24	 *     {slug}-insights.json      — insights scoped to a specific project
 25	 *
 26	 * Locking strategy:
 27	 *   - All read-modify-write sequences (addInsight, updateInsight, deleteInsight)
 28	 *     acquire a single lock on knowledgeDir() for the entire operation.
 29	 *   - All writes use atomicWriteJson() — write-to-temp-then-rename.
 30	 *   - Pure reads (readGlobalStore, readProjectStore, searchInsights, listInsights)
 31	 *     do not acquire a lock, consistent with the LedgerStore pattern.
 32	 *
 33	 * scope === 'project' + project_slug constraint:
 34	 *   The Zod schema accepts project_slug as optional to remain context-free.
 35	 *   This class enforces the constraint: addInsight() throws if scope is 'project'
 36	 *   and project_slug is absent.
 37	 */
 38	export class KnowledgeStoreManager {
 39	  public readonly ledgerRoot: string;
 40	
 41	  constructor(ledgerRoot: string) {
 42	    this.ledgerRoot = ledgerRoot;
 43	  }
 44	
 45	  // ==================== Path Helpers ====================
 46	
 47	  knowledgeDir(): string {
 48	    return join(this.ledgerRoot, '.knowledge');
 49	  }
 50	
 51	  globalStorePath(): string {
 52	    return join(this.knowledgeDir(), 'global-insights.json');
 53	  }
 54	
 55	  projectStorePath(slug: string): string {
 56	    this._validateSlug(slug);
 57	    return join(this.knowledgeDir(), `${slug}-insights.json`);
 58	  }
 59	
 60	  // ==================== Read Methods ====================
 61	
 62	  /**
 63	   * Reads and validates the global insights store.
 64	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 65	   *
 66	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 67	   */
 68	  async readGlobalStore(): Promise<KnowledgeStore> {
 69	    return this._readStore(this.globalStorePath());
 70	  }
 71	
 72	  /**
 73	   * Reads and validates a project-scoped insights store.
 74	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 75	   *
 76	   * @param slug - Project slug (used to derive the filename)
 77	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 78	   */
 79	  async readProjectStore(slug: string): Promise<KnowledgeStore> {
 80	    return this._readStore(this.projectStorePath(slug));
 81	  }
 82	
 83	  // ==================== Write Methods ====================
 84	
 85	  /**
 86	   * Writes the global insights store atomically under a lock.
 87	   * Validates the data against KnowledgeStoreSchema before writing.
 88	   *
 89	   * @param data - Store data to persist
 90	   * @throws Error if validation fails or write fails
 91	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
 92	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
 93	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
 94	   *   which would deadlock. This method is safe only at the top level.
 95	   */
 96	  async writeGlobalStore(data: KnowledgeStore): Promise<void> {
 97	    await withLock(this.knowledgeDir(), async () => {
 98	      const validated = KnowledgeStoreSchema.parse(data);
 99	      await atomicWriteJson(this.globalStorePath(), validated);
100	    });

101	  }
102	
103	  /**
104	   * Writes a project-scoped insights store atomically under a lock.
105	   * Validates the data against KnowledgeStoreSchema before writing.
106	   *
107	   * @param slug - Project slug
108	   * @param data - Store data to persist
109	   * @throws Error if validation fails or write fails
110	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
111	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
112	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
113	   *   which would deadlock. This method is safe only at the top level.
114	   */
115	  async writeProjectStore(slug: string, data: KnowledgeStore): Promise<void> {
116	    await withLock(this.knowledgeDir(), async () => {
117	      const validated = KnowledgeStoreSchema.parse(data);
118	      await atomicWriteJson(this.projectStorePath(slug), validated);
119	    });
120	  }
121	
122	  // ==================== ID Generation ====================
123	
124	  /**
125	   * Increments the store's next_id counter and returns the formatted ID string.
126	   *
127	   * Mutates the store object in-place — the updated store must be written to disk
128	   * for the counter to persist across process restarts.
129	   *
130	   * @param store - The store whose counter should be incremented
131	   * @returns Formatted ID string in KN-NNNN format (e.g., "KN-0001" for next_id=1)
132	   */
133	  nextId(store: KnowledgeStore): string {
134	    const id = store.next_id;
135	    store.next_id = id + 1;
136	    return `KN-${String(id).padStart(4, '0')}`;
137	  }
138	
139	  // ==================== CRUD Operations ====================
140	
141	  /**
142	   * Adds a new insight to the appropriate store (global or project-scoped).
143	   *
144	   * Assigns the numeric id from the store's next_id counter and persists the
145	   * incremented counter. Enforces the project_slug requirement for project-scoped
146	   * insights. The entire read-modify-write sequence runs under a single lock.
147	   *
148	   * @param input - Insight data without the id field (auto-assigned from next_id)
149	   * @returns The created Insight with the assigned numeric id
150	   * @throws Error if scope === 'project' and project_slug is absent
151	   */
152	  async addInsight(input: Omit<Insight, 'id'>): Promise<Insight> {
153	    if (input.scope === 'project' && !input.project_slug) {
154	      throw new Error('project_slug is required for project-scoped insights');
155	    }
156	
157	    return await withLock(this.knowledgeDir(), async () => {
158	      const storePath =
159	        input.scope === 'global'
160	          ? this.globalStorePath()
161	          : this.projectStorePath(input.project_slug!);
162	
163	      const store = await this._readStore(storePath);
164	
165	      // Save the numeric id before nextId increments the counter.
166	      // The KN-NNNN return value of nextId() is intentionally discarded here —
167	      // display-format IDs are produced by MCP tool layer consumers, not stored.
168	      const numericId = store.next_id;
169	      this.nextId(store);
170	
171	      const insight: Insight = InsightSchema.parse({ ...input, id: numericId });
172	      store.insights.push(insight);
173	      store.last_updated = now();
174	
175	      const validated = KnowledgeStoreSchema.parse(store);
176	      await atomicWriteJson(storePath, validated);
177	
178	      return insight;
179	    });
180	  }
181	
182	  /**
183	   * Searches insights across all (or filtered) stores for the query string.
184	   *
185	   * Applies a case-insensitive substring match against title, content, and every
186	   * entry in the tags array.
187	   *
188	   * @param query - Substring to search for
189	   * @param filters - Optional scope/category/project_slug filters to narrow the stores searched
190	   * @returns Insights matching the query
191	   */
192	  async searchInsights(
193	    query: string,
194	    filters?: { scope?: InsightScope; project_slug?: string; category?: string }
195	  ): Promise<Insight[]> {
196	    const allInsights = await this._loadInsights(filters);
197	    const q = query.toLowerCase();
198	
199	    return allInsights.filter(
200	      (insight) =>
201	        insight.title.toLowerCase().includes(q) ||
202	        insight.content.toLowerCase().includes(q) ||
203	        insight.tags.some((tag) => tag.toLowerCase().includes(q))
204	    );
205	  }
206	
207	  /**
208	   * Lists insights with optional scope/category/tags/project_slug filters and pagination.
209	   *
210	   * Filters are applied in this order: store selection (scope/project_slug) → category →
211	   * tags → offset → limit.
212	   *
213	   * @param filters - Scope, category, tags, project_slug filters; limit and offset for pagination
214	   * @returns Filtered and paginated insight array
215	   */
216	  async listInsights(filters: {
217	    scope?: InsightScope;
218	    category?: string;
219	    tags?: string[];
220	    project_slug?: string;
221	    limit?: number;
222	    offset?: number;
223	  }): Promise<Insight[]> {
224	    const { limit, offset = 0, tags: tagFilter, ...loadFilters } = filters;
225	
226	    let insights = await this._loadInsights(loadFilters);
227	
228	    if (tagFilter && tagFilter.length > 0) {
229	      insights = insights.filter((insight) =>
230	        tagFilter.every((tag) => insight.tags.includes(tag))
231	      );
232	    }
233	
234	    return insights.slice(offset, limit !== undefined ? offset + limit : undefined);
235	  }
236	
237	  /**
238	   * Updates an existing insight by numeric ID.
239	   *
240	   * When `filter.scope` and/or `filter.project_slug` are provided the search is
241	   * restricted to the matching store(s), preventing accidental global-insight
242	   * mutation when the same numeric ID exists in multiple stores. Without a
243	   * filter, all stores are scanned (original behaviour — preserved for
244	   * backwards compatibility).
245	   *
246	   * Applies the provided partial updates and sets updated_at to the current
247	   * timestamp. The entire read-modify-write sequence runs under a single lock.
248	   *
249	   * Immutable fields (id, scope, project_slug, created_at) are not accepted
250	   * in the updates parameter.
251	   *
252	   * @param id - Numeric insight id
253	   * @param updates - Partial insight fields to update
254	   * @param filter - Optional scope/project_slug filter to restrict which store is searched
255	   * @returns The updated Insight
256	   * @throws Error if no insight with the given id exists in the filtered stores
257	   */
258	  async updateInsight(
259	    id: number,
260	    updates: Partial<
261	      Pick<Insight, 'title' | 'content' | 'category' | 'tags' | 'source' | 'confidence' | 'superseded_by'>
262	    >,
263	    filter?: { scope?: InsightScope; project_slug?: string }
264	  ): Promise<Insight> {
265	    return await withLock(this.knowledgeDir(), async () => {
266	      const storePaths = await this._storePathsForFilter(filter);
267	
268	      for (const storePath of storePaths) {
269	        const store = await this._readStore(storePath);
270	        const idx = store.insights.findIndex((i) => i.id === id);
271	
272	        if (idx === -1) continue;
273	
274	        const updatedInsight: Insight = InsightSchema.parse({
275	          ...store.insights[idx],
276	          ...updates,
277	          updated_at: now(),
278	        });
279	
280	        store.insights[idx] = updatedInsight;
281	        store.last_updated = now();
282	
283	        const validated = KnowledgeStoreSchema.parse(store);
284	        await atomicWriteJson(storePath, validated);
285	
286	        return updatedInsight;
287	      }
288	
289	      throw new Error(`Insight with id ${id} not found`);
290	    });
291	  }
292	
293	  /**
294	   * Moves an insight from one store to another in a single atomic lock span,
295	   * eliminating the TOCTOU window inherent in the previous add→delete two-step pattern.
296	   *
297	   * The operation performs these steps inside a single withLock(knowledgeDir) span:
298	   *   1. Resolve the source store path(s) from sourceFilter.
299	   *   2. Find the insight by id in the source store — throws if not found.
300	   *   3. Construct the moved insight: new id (from the target store's next_id counter),
301	   *      corrected scope/project_slug, and a fresh updated_at timestamp.
302	   *   4. Validate the new insight with InsightSchema.parse(…).
303	   *   5. Write the updated target store (with the new insight appended) via atomicWriteJson.
304	   *   6. Remove the original insight from the source store and write it via atomicWriteJson.
305	   *
306	   * @param id - Numeric id of the insight to move
307	   * @param sourceFilter - Scope (and optional project_slug) of the store containing the insight
308	   * @param targetScope - Destination scope ('global' or 'project')
309	   * @param targetProjectSlug - Required when targetScope === 'project'
310	   * @returns The moved Insight with new id, corrected scope/project_slug, and updated_at
311	   * @throws Error if the insight is not found in the source store(s)
312	   * @throws Error if targetScope === 'project' and targetProjectSlug is absent
313	   * @warning Do NOT call from inside a withLock(knowledgeDir, …) callback.
314	   *   This method acquires the lock itself; a nested call would deadlock.
315	   */
316	  async moveInsight(
317	    id: number,
318	    sourceFilter: { scope: InsightScope; project_slug?: string },
319	    targetScope: InsightScope,
320	    targetProjectSlug?: string
321	  ): Promise<Insight> {
322	    if (targetScope === 'project' && !targetProjectSlug) {
323	      throw new Error('targetProjectSlug is required when targetScope is "project"');
324	    }
325	
326	    return await withLock(this.knowledgeDir(), async () => {
327	      // 1. Resolve source path(s)
328	      const sourcePaths = await this._storePathsForFilter(sourceFilter);
329	
330	      // 2. Find insight in source store
331	      let sourceStorePath: string | undefined;
332	      let sourceStore: KnowledgeStore | undefined;
333	      let sourceIdx = -1;
334	
335	      for (const storePath of sourcePaths) {
336	        const store = await this._readStore(storePath);
337	        const idx = store.insights.findIndex((i) => i.id === id);
338	        if (idx !== -1) {
339	          sourceStorePath = storePath;
340	          sourceStore = store;
341	          sourceIdx = idx;
342	          break;
343	        }
344	      }
345	
346	      if (!sourceStorePath || !sourceStore || sourceIdx === -1) {
347	        throw new Error(`Insight with id ${id} not found`);
348	      }
349	
